// Embedded cartoon boing selected by the user; see assets/SOURCES.md.
const BounceAudio=(()=>{
 let context=null,master=null,muted=false,voices=0,sample=null,loading=null;
 const activeVoices=new Set();
 let splatNoise=null,knockSample=null,lastSplat=-10;
 try{muted=localStorage.getItem('death-chamber-muted')==='true';}catch{}
 // Embedded bytes also work on file:// pages without fetch/CORS restrictions.
 const boingData='';
 const button=document.getElementById('sound');
 function unlock(){
  if(muted)return;
  try{
   const AudioContextClass=globalThis.AudioContext||globalThis.webkitAudioContext;
   if(!AudioContextClass)return;
   if(!context||context.state==='closed'){
    context=new AudioContextClass({latencyHint:'interactive'});master=context.createGain();
    master.gain.value=muted?0:.45;master.connect(context.destination);
   }
   if(context.state==='suspended')context.resume().catch(()=>{});
   loadSample();
  }catch{/* Audio availability must never interrupt play. */}
 }
 function loadSample(){
  if(!context||sample||loading)return;
  loading=Promise.resolve()
   .then(()=>Uint8Array.from(atob(boingData),character=>character.charCodeAt(0)).buffer)
   .then(bytes=>context.decodeAudioData(bytes))
   .then(decoded=>{
    // Remove leading silence but preserve the reference recording and its tail.
    let peak=0;
    for(let channel=0;channel<decoded.numberOfChannels;channel++){
     const data=decoded.getChannelData(channel);
     for(let i=0;i<data.length;i++)peak=Math.max(peak,Math.abs(data[i]));
    }
    // Search the entire recording for a sustained audible attack. A tiny early
    // click must not leave a long quiet lead-in attached to the boing.
    const windowSize=Math.max(1,Math.round(decoded.sampleRate*.004));
    let onset=0,loudWindows=0;
    for(let offset=0;offset<decoded.length;offset+=windowSize){
     let audible=false;
     for(let channel=0;channel<decoded.numberOfChannels;channel++){
      const data=decoded.getChannelData(channel),end=Math.min(decoded.length,offset+windowSize);
      let energy=0,windowPeak=0;
      for(let i=offset;i<end;i++){energy+=data[i]*data[i];windowPeak=Math.max(windowPeak,Math.abs(data[i]));}
      if(Math.sqrt(energy/Math.max(1,end-offset))>peak*.045&&windowPeak>peak*.12)audible=true;
     }
     loudWindows=audible?loudWindows+1:0;
     if(loudWindows>=2){onset=Math.max(0,offset-windowSize-Math.round(decoded.sampleRate*.001));break;}
    }
    const length=decoded.length-onset;
    sample=context.createBuffer(decoded.numberOfChannels,length,decoded.sampleRate);
    const normalise=Math.min(3,.75/Math.max(.01,peak));
    for(let channel=0;channel<decoded.numberOfChannels;channel++){
     const input=decoded.getChannelData(channel),output=sample.getChannelData(channel);
     for(let i=0;i<length;i++){
      const fade=Math.min(1,i/(decoded.sampleRate*.001),(length-1-i)/(decoded.sampleRate*.025));
      output[i]=input[onset+i]*normalise*Math.max(0,fade);
     }
    }
   })
   .catch(()=>{if(button)button.title='Click to retry loading the boing sound.';})
   .finally(()=>{loading=null;});
 }
 function boing(landingSpeed){
  if(!context||context.state!=='running'||!sample||muted||voices>=6||document.hidden)return;
  const strength=Math.max(0,Math.min(1,Math.abs(landingSpeed)/1200));
  const now=context.currentTime,rate=Math.pow(2,(4-strength*8)/12),duration=sample.duration/rate;
  const source=context.createBufferSource(),envelope=context.createGain();
  source.buffer=sample;source.playbackRate.setValueAtTime(rate,now);
  envelope.gain.setValueAtTime(.0001,now);
  envelope.gain.exponentialRampToValueAtTime(.28+strength*.58,now+.003);
  envelope.gain.setValueAtTime(.28+strength*.58,now+Math.max(.004,duration-.04));
  envelope.gain.exponentialRampToValueAtTime(.0001,now+duration);
  source.connect(envelope);envelope.connect(master);
  const voice={source,envelope,kind:'boing'};activeVoices.add(voice);voices=activeVoices.size;
  source.onended=()=>{activeVoices.delete(voice);voices=activeVoices.size;source.disconnect();envelope.disconnect();};
  source.start(now);source.stop(now+duration+.01);
 }
 function splat(mass=8,speed=150){
  if(!context||context.state!=='running'||muted||voices>=4||document.hidden||context.currentTime-lastSplat<.075)return;
  lastSplat=context.currentTime;
  if(!splatNoise){
   const length=Math.round(context.sampleRate*.16);splatNoise=context.createBuffer(1,length,context.sampleRate);
   const data=splatNoise.getChannelData(0);let seed=173;
   for(let i=0;i<length;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;data[i]=(seed/4294967296*2-1)*Math.pow(1-i/length,1.6);}
  }
  const now=context.currentTime,duration=.18;
  const source=context.createBufferSource(),bubble=context.createOscillator(),filter=context.createBiquadFilter(),envelope=context.createGain(),bubbleMix=context.createGain();
  source.buffer=splatNoise;filter.type='lowpass';filter.Q.value=2;
  filter.frequency.setValueAtTime(1700,now);filter.frequency.exponentialRampToValueAtTime(300,now+.14);
  bubble.type='sine';bubble.frequency.setValueAtTime(260,now);bubble.frequency.exponentialRampToValueAtTime(65,now+.13);bubbleMix.gain.value=.22;
  envelope.gain.setValueAtTime(.0001,now);
  envelope.gain.exponentialRampToValueAtTime(.13+Math.min(1,mass/24)*.13,now+.003);
  envelope.gain.exponentialRampToValueAtTime(.0001,now+duration);
  source.connect(filter);filter.connect(envelope);bubble.connect(bubbleMix);bubbleMix.connect(envelope);envelope.connect(master);
  const voice={source,envelope,extraSources:[bubble]};activeVoices.add(voice);voices=activeVoices.size;
  bubble.onended=()=>{activeVoices.delete(voice);voices=activeVoices.size;for(const n of [source,bubble,filter,envelope,bubbleMix])n.disconnect();};
  source.start(now);bubble.start(now);source.stop(now+duration+.01);bubble.stop(now+duration+.01);
 }
 function impact(speed,softness=1){
  // Reserve room above normal effects so pain knocks aren't lost under splats.
  if(!context||context.state!=='running'||muted||voices>=10||document.hidden)return;
  if(!knockSample){
   const rate=context.sampleRate,length=Math.round(rate*.17);
   knockSample=context.createBuffer(1,length,rate);const data=knockSample.getChannelData(0);
   for(let i=0;i<length;i++){
    const t=i/rate;
    const tok=time=>time<0?0:Math.min(1,time/.001)*(.65*Math.sin(2*Math.PI*570*time)*Math.exp(-time*65)+.3*Math.sin(2*Math.PI*1030*time)*Math.exp(-time*95)+.15*Math.sin(2*Math.PI*1770*time)*Math.exp(-time*130));
    data[i]=tok(t)+.35*tok(t-.048);
   }
  }
  const strength=Math.max(0,Math.min(1,(Math.abs(speed)-220)/1000)),now=context.currentTime;
  const source=context.createBufferSource(),envelope=context.createGain();source.buffer=knockSample;
  source.playbackRate.setValueAtTime(1.1-strength*.22,now);
  envelope.gain.setValueAtTime(.0001,now);
  envelope.gain.exponentialRampToValueAtTime((.55+strength*.25)*Math.max(.7,softness),now+.001);
  envelope.gain.exponentialRampToValueAtTime(.0001,now+.2);
  source.connect(envelope);envelope.connect(master);
  const voice={source,envelope,kind:'impact'};activeVoices.add(voice);voices=activeVoices.size;
  source.onended=()=>{activeVoices.delete(voice);voices=activeVoices.size;source.disconnect();envelope.disconnect();};
  source.start(now);source.stop(now+.21);
 }
 function setMuted(value,persist=true){
  muted=Boolean(value);
  if(master){
   master.gain.cancelScheduledValues(context.currentTime);
   master.gain.setValueAtTime(muted?0:.45,context.currentTime);
  }
  if(muted){
   // Silence both the current ringing tail and any already scheduled voices.
   for(const voice of activeVoices){
    voice.envelope.gain.cancelScheduledValues(context.currentTime);
    voice.envelope.gain.setValueAtTime(0,context.currentTime);
    for(const source of [voice.source,...(voice.extraSources||[])])try{source.stop(context.currentTime);}catch{}
   }
  }
  if(button){button.textContent=muted?'Sound: off':'Sound: on';button.setAttribute('aria-pressed',String(muted));button.setAttribute('aria-label',muted?'Unmute sound':'Mute sound');}
  if(persist)try{localStorage.setItem('death-chamber-muted',String(muted));}catch{}
 }
 button?.addEventListener('click',()=>{setMuted(!muted);if(!muted)unlock();});
 globalThis.addEventListener?.('storage',e=>{if(e.key==='death-chamber-muted')setMuted(e.newValue==='true',false);});
 setMuted(muted,false);
 document.addEventListener('pointerdown',unlock,{capture:true});
 document.addEventListener('keydown',unlock,{capture:true});
 return {unlock,boing,impact,splat};
})();
